def record_github_users(apps, schema_editor):
    """A GitHub user for every person who signed in with GitHub, linked to them."""
    Profile = apps.get_model("pycal_dashboard", "Profile")
    GitHubUser = apps.get_model("pycal_dashboard", "GitHubUser")
    SocialAccount = apps.get_model("socialaccount", "SocialAccount")
    for profile in Profile.objects.exclude(github_id=""):
        if not profile.github_id.isdigit():
            continue
        account = SocialAccount.objects.filter(user_id=profile.user_id, provider="github").first()
        data = (account.extra_data or {}) if account else {}
        GitHubUser.objects.update_or_create(
            github_id=int(profile.github_id),
            defaults={
                "login": profile.github_name,
                "name": str(data.get("name") or ""),
                "avatar_url": str(data.get("avatar_url") or ""),
                "type": str(data.get("type") or ""),
                "user_id": profile.user_id,
            },
        )


